(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-204":{scenario:{company:"Seabridge Logistics",supervisor:{name:"Lý Văn Tâm",role:{vi:"Trưởng bộ phận Hiện trường Cảng",en:"Port Field Operations Lead"}},ref_code:"BKG-6618",title:{vi:"Đúng loại container. Đúng VGM. Đúng niêm phong.",en:"Right container type. Right VGM. Right seal."},brief:{vi:"Bạn phụ trách hiện trường lô xuất khẩu BKG-6618 tại cảng. Container thực tế là loại 40 feet cao (high cube) hàng khô, biển CSC ghi trọng lượng vỏ 3880 kg. Hàng gồm 2150 thùng tổng 17760 kg, pallet và vật liệu chèn lót 540 kg. Hãng tàu yêu cầu VGM theo phương pháp 2 của SOLAS. Bản nháp khai mã kích thước - loại 42G1 và VGM chưa gồm vỏ container. Hãy sửa hai trường trước giờ cắt máng và lập báo cáo có căn cứ.",en:"You are the field officer for export booking BKG-6618 at the port. The actual container is a 40-foot high cube dry box; its CSC plate shows a tare of 3880 kg. Cargo is 2150 cartons totalling 17760 kg, with 540 kg of pallets and dunnage. The carrier requires VGM under SOLAS method 2. The draft declares size-type code 42G1 and a VGM without the container tare. Correct both fields before cut-off and write an evidence-based report."},reference_title:{vi:"Phiếu EIR, biển CSC & phiếu cân đã xác nhận · BKG-6618",en:"Confirmed EIR, CSC plate & weighing slips · BKG-6618"},fields:[{id:"ISO_TYPE",label:{vi:"Mã kích thước - loại container (ISO 6346)",en:"Container size-type code (ISO 6346)"},initial:"42G1",expected:"45G1",choices:["22G1","42G1","45G1"],reference:"Phiếu giao nhận container (EIR)",ref_value:{vi:"Dài 40 feet, cao 9 feet 6 inch (high cube), container hàng khô thông dụng",en:"40 feet long, 9 feet 6 inches high (high cube), general purpose dry container"},hint:{vi:"Ký tự đầu của mã là chiều dài, ký tự thứ hai là chiều cao: 2 là 8 feet 6 inch, 5 là 9 feet 6 inch.",en:"The first character is length and the second is height: 2 means 8 feet 6 inches, 5 means 9 feet 6 inches."}},{id:"VGM_KG",label:{vi:"VGM khai báo (kg)",en:"Declared VGM (kg)"},initial:"18300",expected:"22180",reference:"Phiếu cân hàng và biển CSC",ref_value:{vi:"Hàng 17760 kg; pallet, chèn lót 540 kg; vỏ theo biển CSC 3880 kg",en:"Cargo 17760 kg; pallets and dunnage 540 kg; CSC plate tare 3880 kg"},hint:{vi:"Phương pháp 2 cộng toàn bộ hàng, vật liệu đóng gói, chèn lót và trọng lượng vỏ container.",en:"Method 2 adds all cargo, packing, dunnage and the container tare."}}],sop32:{vi:"VGM (phương pháp 2) = khối lượng hàng + pallet, vật liệu đóng gói, chèn lót + trọng lượng vỏ container theo biển CSC; VGM phải gửi hãng tàu trước giờ cắt máng.",en:"VGM (method 2) = cargo mass + pallets, packing and dunnage + container tare per the CSC plate; submit VGM to the carrier before cut-off."},context:{label:"PORT OPS / BKG-6618",metrics:[{label:{vi:"Vỏ container theo CSC",en:"CSC plate tare"},value:"3,880 kg"},{label:{vi:"Khối lượng hàng",en:"Cargo mass"},value:"17,760 kg"},{label:{vi:"Pallet và chèn lót",en:"Pallets & dunnage"},value:"540 kg"}]},crisis:{vi:"Chủ hàng gọi: “Container đã kiểm hóa và niêm phong rồi. Em cắt seal cho bên anh đóng thêm 120 thùng chưa khai, bấm seal mới rồi hạ bãi luôn, tờ khai để sau tính.”",en:"The shipper calls: “The container has been inspected and sealed. Cut the seal so we can load 120 more undeclared cartons, fit a new seal and send it to the yard. We will deal with the declaration later.”"},options:{safe:{vi:"Từ chối cắt seal, báo Trưởng bộ phận hiện trường; nếu cần bổ sung hàng thì làm thủ tục khai bổ sung hoặc tờ khai mới theo quy định và cập nhật VGM trước khi hạ bãi.",en:"Refuse to cut the seal and inform the field operations lead; if cargo must be added, file an amendment or a new declaration as required and update the VGM before gate-in."},shortcut:{vi:"Cắt seal, đóng thêm hàng và bấm seal mới cho kịp tàu.",en:"Cut the seal, add the cargo and fit a new seal to make the vessel."},wait:{vi:"Không xử lý, để container nằm ngoài bãi chờ chủ hàng tự lo.",en:"Do nothing and leave the container outside the yard for the shipper to sort out."}},questions:{vi:["Vì sao mã đúng là 45G1 và VGM là 22180 kg? Hãy dẫn phiếu EIR, biển CSC, phiếu cân và yêu cầu SOLAS.","Cắt seal để đóng thêm hàng chưa khai gây rủi ro pháp lý, an toàn gì và bạn báo cáo cho ai?"],en:["Why is the correct code 45G1 and the VGM 22180 kg? Cite the EIR, the CSC plate, the weighing slips and the SOLAS rule.","What legal and safety risks arise from cutting the seal to load undeclared cargo, and whom do you report to?"]},hints:{vi:["Đối chiếu chiều dài, chiều cao container thực tế trên EIR với cấu trúc mã ISO 6346.","Cộng đủ ba thành phần khối lượng theo phương pháp 2 ở SOP mục 3.2.","Đọc SOP mục 4.2: không cắt seal hay thay đổi hàng sau kiểm hóa khi chưa có thủ tục hợp lệ."],en:["Match the actual length and height on the EIR with the ISO 6346 code structure.","Add all three mass components under method 2 in SOP 3.2.","Re-read SOP 4.2: never cut a seal or change cargo after inspection without a valid procedure."]}},learning:{summary:{vi:"Chuyên viên hiện trường xuất nhập khẩu đại diện doanh nghiệp tại cảng, cửa khẩu, kho bãi: làm thủ tục giao nhận container, phối hợp kiểm hóa với hải quan, kiểm tra seal, VGM, chứng từ lấy hàng, thanh lý tờ khai và xử lý sự cố phát sinh. Nghề giúp hàng thông quan và lên tàu đúng giờ, đòi hỏi am hiểu thủ tục hải quan, vận tải container, khả năng ứng biến và nguyên tắc liêm chính tại hiện trường.",en:"A customs clearance field officer represents the company at ports, border gates and depots: handling container interchange, coordinating customs inspections, checking seals, VGM and release documents, finalising declarations and solving incidents on the spot. The role gets cargo cleared and loaded on time and requires knowledge of customs procedures and container transport, quick thinking and integrity in the field."},responsibilities:{vi:["Nhận lệnh cấp container, kiểm tra tình trạng vỏ, mã ISO và biển CSC.","Giám sát đóng hàng, niêm phong và đối chiếu số seal với chứng từ.","Gửi VGM, hạ bãi container đúng giờ cắt máng của hãng tàu.","Xuất trình hồ sơ, phối hợp kiểm hóa và xử lý yêu cầu của hải quan tại hiện trường.","Lấy hàng nhập, thanh lý tờ khai và báo cáo sự cố cho bộ phận chứng từ."],en:["Collect empty containers and check condition, ISO code and CSC plate.","Supervise stuffing and sealing and match seal numbers with documents.","Submit the VGM and gate in containers before the carrier's cut-off.","Present files, coordinate inspections and handle customs requests on site.","Collect import cargo, finalise declarations and report incidents to the documentation team."]},competencies:[{name:{vi:"Nghiệp vụ container",en:"Container know-how"},desc:{vi:"Đọc mã ISO 6346, biển CSC, phân biệt loại container và kiểm tra tình trạng vỏ.",en:"Read ISO 6346 codes and CSC plates, tell container types apart and inspect boxes."}},{name:{vi:"Thủ tục hải quan hiện trường",en:"Field customs procedures"},desc:{vi:"Nắm quy trình phân luồng, kiểm hóa, giám sát và thanh lý tờ khai tại cảng.",en:"Know channel routing, inspection, supervision and declaration finalisation at the port."}},{name:{vi:"Chính xác số liệu",en:"Data accuracy"},desc:{vi:"Ghi đúng số container, số seal, VGM và đối chiếu với booking, tờ khai.",en:"Record container numbers, seal numbers and VGM correctly against booking and declaration."}},{name:{vi:"Xử lý sự cố",en:"Incident handling"},desc:{vi:"Bình tĩnh xử lý container hỏng, sai seal, trễ cắt máng và báo cáo kịp thời.",en:"Calmly handle damaged boxes, seal mismatches and late cut-offs and report promptly."}},{name:{vi:"Liêm chính hiện trường",en:"Field integrity"},desc:{vi:"Từ chối cắt seal, thêm bớt hàng hay đưa lợi ích trái quy định để kịp tàu.",en:"Refuse to cut seals, add or remove cargo or offer improper benefits to catch a vessel."}}],knowledge:{vi:["Luật Hải quan số 54/2014/QH13 và quy định về kiểm tra, giám sát hải quan tại cảng.","Công ước SOLAS chương VI quy định 2 về khối lượng toàn bộ container đã xác minh (VGM), áp dụng từ 01/7/2016.","ISO 6346 về mã chủ sở hữu, số container, chữ số kiểm tra và mã kích thước - loại.","Công ước CSC về an toàn container và biển phê duyệt an toàn gắn trên vỏ.","ISO 17712 về seal cơ khí an ninh cho container.","Quy trình giao nhận tại cảng: EIR, lệnh giao hàng (D/O), cắt máng, hạ bãi, thanh lý tờ khai."],en:["Customs Law No. 54/2014/QH13 and rules on customs inspection and supervision at ports.","SOLAS Chapter VI Regulation 2 on verified gross mass (VGM), in force since 1 July 2016.","ISO 6346 on owner codes, container numbers, check digits and size-type codes.","The CSC Convention on safe containers and the safety approval plate.","ISO 17712 on mechanical security seals for containers.","Port interchange: EIR, delivery order (D/O), cut-off, gate-in and declaration finalisation."]},tools:["VNACCS/VCIS","Port e-portal & eDO","VGM submission portal","Seal & container photo app","Weighbridge ticket","Mobile document scanner"],tools_en:["VNACCS/VCIS","Port e-portal & eDO","VGM submission portal","Seal & container photo app","Weighbridge ticket","Mobile document scanner"],kpis:{vi:["Tỷ lệ container hạ bãi kịp giờ cắt máng.","Số sai lệch số seal, mã container, VGM so với chứng từ (mục tiêu bằng 0).","Thời gian thông quan trung bình tại hiện trường.","Chi phí phát sinh do lưu container, lưu bãi vì lỗi hiện trường."],en:["Share of containers gated in before cut-off.","Seal, container code or VGM mismatches with documents (target zero).","Average field clearance time.","Demurrage and storage costs caused by field errors."]},day:[{time:"06:30",vi:"Nhận container rỗng tại depot, kiểm tra vỏ, mã ISO và biển CSC.",en:"Pick up empties at the depot and check the box, ISO code and CSC plate."},{time:"08:30",vi:"Giám sát đóng hàng tại kho, chụp ảnh và bấm seal.",en:"Supervise stuffing at the warehouse, take photos and fit the seal."},{time:"11:00",vi:"Gửi VGM cho hãng tàu và chuẩn bị hồ sơ kiểm hóa.",en:"Submit the VGM to the carrier and prepare inspection files."},{time:"14:00",vi:"Phối hợp hải quan kiểm hóa container luồng đỏ tại bãi.",en:"Coordinate customs inspection of a red channel container in the yard."},{time:"16:30",vi:"Hạ bãi trước cắt máng, thanh lý tờ khai và báo cáo cho văn phòng.",en:"Gate in before cut-off, finalise the declaration and report to the office."}],mistakes:{vi:["Khai 42G1 cho container high cube, làm sai kế hoạch xếp tàu và dữ liệu khai báo.","Khai VGM chỉ gồm hàng và bao bì, quên trọng lượng vỏ container.","Cắt seal đóng thêm hàng sau kiểm hóa theo yêu cầu chủ hàng mà không làm thủ tục."],en:["Declaring 42G1 for a high cube box, corrupting stowage plans and declaration data.","Declaring a VGM with cargo and packing only, forgetting the container tare.","Cutting a seal to add cargo after inspection at the shipper's request without any procedure."]},career:[{vi:"Nhân viên giao nhận hiện trường",en:"Field forwarding assistant"},{vi:"Chuyên viên hiện trường xuất nhập khẩu",en:"Customs clearance field officer"},{vi:"Trưởng nhóm hiện trường cảng",en:"Port field team lead"},{vi:"Quản lý vận hành giao nhận & hải quan",en:"Forwarding & customs operations manager"}],glossary:[{term:"VGM",vi:"Khối lượng toàn bộ container đã xác minh, gồm hàng, vật liệu đóng gói và vỏ container.",en:"Verified gross mass of a packed container, including cargo, packing and tare."},{term:"CSC plate",vi:"Biển phê duyệt an toàn trên vỏ container, ghi trọng lượng vỏ và tổng trọng lượng tối đa.",en:"The safety approval plate on a container showing tare and maximum gross mass."},{term:"ISO 6346",vi:"Tiêu chuẩn mã hóa container: mã chủ sở hữu, số sê-ri, chữ số kiểm tra và mã kích thước - loại.",en:"The container coding standard: owner code, serial number, check digit and size-type code."},{term:"EIR",vi:"Phiếu giao nhận container ghi tình trạng vỏ, số seal khi container ra vào cảng, depot.",en:"Equipment interchange receipt recording box condition and seal number at each gate move."},{term:"Cut-off",vi:"Giờ cắt máng: thời hạn cuối hạ container, gửi VGM và chứng từ trước khi tàu chạy.",en:"The deadline to gate in containers and send VGM and documents before sailing."}],quiz:[{q:{vi:"Mã 22G1 theo ISO 6346 là loại container nào?",en:"Which container does ISO 6346 code 22G1 describe?"},options:{vi:["Container 40 feet cao","Container 20 feet hàng khô thông dụng, cao 8 feet 6 inch","Container lạnh 40 feet","Container mở nóc 20 feet"],en:["A 40-foot high cube","A 20-foot general purpose dry box, 8 feet 6 inches high","A 40-foot reefer","A 20-foot open top"]},answer:1,explain:{vi:"Ký tự 2 đầu tiên là 20 feet, ký tự 2 thứ hai là cao 8 feet 6 inch, G1 là container hàng khô thông dụng.",en:"The first 2 means 20 feet, the second 2 means 8 feet 6 inches high, and G1 is a general purpose dry box."}},{q:{vi:"Hàng 12000 kg, pallet 300 kg, vỏ container 2200 kg. VGM theo phương pháp 2 là bao nhiêu?",en:"Cargo 12000 kg, pallets 300 kg, container tare 2200 kg. What is the VGM under method 2?"},options:{vi:["12300 kg","14200 kg","12000 kg","14500 kg"],en:["12300 kg","14200 kg","12000 kg","14500 kg"]},answer:3,explain:{vi:"VGM = hàng 12000 + pallet 300 + vỏ 2200 = 14500 kg.",en:"VGM = 12000 + 300 + 2200 = 14500 kg."}},{q:{vi:"Chủ hàng đề nghị cắt seal đóng thêm hàng chưa khai sau khi đã kiểm hóa. Bạn làm gì?",en:"The shipper asks you to cut the seal and add undeclared cargo after inspection. What do you do?"},options:{vi:["Từ chối, báo cấp trên và chỉ bổ sung hàng khi đã làm thủ tục hợp lệ","Làm theo cho kịp tàu","Cắt seal nhưng chụp ảnh lưu lại","Nhờ tài xế làm hộ"],en:["Refuse, inform your lead and add cargo only after a valid procedure","Comply to make the vessel","Cut the seal but keep photos","Ask the driver to do it"]},answer:0,explain:{vi:"Đóng thêm hàng chưa khai là vi phạm pháp luật hải quan và làm sai VGM, ảnh hưởng an toàn xếp tàu.",en:"Adding undeclared cargo breaches customs law and falsifies the VGM, endangering stowage safety."}},{q:{vi:"Theo SOLAS, ai chịu trách nhiệm cung cấp VGM cho hãng tàu?",en:"Under SOLAS, who is responsible for providing the VGM to the carrier?"},options:{vi:["Cảng vụ","Thuyền trưởng","Người gửi hàng có tên trên vận đơn","Cơ quan hải quan"],en:["The port authority","The ship's master","The shipper named on the bill of lading","The customs authority"]},answer:2,explain:{vi:"SOLAS quy định người gửi hàng ghi trên vận đơn có trách nhiệm xác minh và cung cấp VGM.",en:"SOLAS makes the shipper named on the bill of lading responsible for verifying and providing the VGM."}}]}}})})(window.KKR);
